  "implementation": "from collections import deque

def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    removed = set()
    # initial queue: descending depth, then stable node id order
    sorted_ids = sorted(node_map.keys(), key=lambda x: (-node_map[x]['depth'], x))
    queue = deque(sorted_ids)
    visit_order = []
    while queue:
        nid = queue.popleft()
        visit_order.append(nid)
        if nid in removed:
            continue
        nd = node_map[nid]
        # check if leaf (no remaining children)
        child_ids = children.get(nid, [])
        has_child = any(cid not in removed for cid in child_ids)
        if has_child:
            continue
        if not nd['removable']:
            continue
        if nd['utility'] > threshold:
            continue
        # remove this node
        removed.add(nid)
        parent = nd['parent']
        if parent is not None and parent not in removed:
            queue.append(parent)
    retained = [n['id'] for n in nodes if n['id'] not in removed]
    return {'retained_node_ids': retained, 'visit_order': visit_order}
